`timescale 1ns/1ps
// Generated by uvmgen from the verification plan. Do not edit.
module tb;
    logic clk = 1'b0;
    logic rst_n = 1'b0;
    logic wr_valid;
    logic [7:0] wr_data;
    logic rd_ready;
    logic wr_ready;
    logic exp_wr_ready;
    bit   chk_wr_ready;
    logic rd_valid;
    logic exp_rd_valid;
    bit   chk_rd_valid;
    logic [7:0] rd_data;
    logic [7:0] exp_rd_data;
    bit   chk_rd_data;
    logic [3:0] count;
    logic [3:0] exp_count;
    bit   chk_count;

    sync_fifo #(.W(8), .DEPTH(8)) dut (.clk(clk), .rst_n(rst_n), .wr_valid(wr_valid), .wr_data(wr_data), .wr_ready(wr_ready), .rd_valid(rd_valid), .rd_data(rd_data), .rd_ready(rd_ready), .count(count));

    always #5.0 clk = ~clk;

    // ---------------- reference model ----------------
    logic [7:0] m_q [8];
    int m_head;
    int m_count;
    bit m_push, m_pop;
    function automatic void m_reset();
        m_head = 0;
        m_count = 0;
    endfunction
    function automatic void m_outputs();
        chk_wr_ready = 1'b1;
        chk_rd_valid = 1'b1;
        chk_rd_data = 1'b1;
        chk_count = 1'b1;
        exp_wr_ready = (m_count != 8);
        exp_rd_valid = (m_count != 0);
        exp_rd_data  = m_q[m_head];
        chk_rd_data  = (m_count != 0);
        exp_count    = 4'(m_count);
    endfunction
    function automatic void m_step();
        // decide both handshakes on the state BEFORE the edge: a full FIFO refuses
        // a write even when a read happens in the same cycle (spec: no bypass)
        m_push = wr_valid && (m_count != 8);
        m_pop  = rd_ready && (m_count != 0);
        if (m_push) m_q[(m_head + m_count) % 8] = wr_data;
        if (m_pop)  m_head = (m_head + 1) % 8;
        m_count = m_count + int'(m_push) - int'(m_pop);
    endfunction

    // ---------------- sequence variables ----------------
    int i;

    // ---------------- scoreboard + coverage ----------------
    int cov_hits [7];
    int errors = 0, checks = 0, cyc = 0;
    string cur_seq;
    task automatic check();
        m_outputs();
        checks++;
        if (chk_wr_ready && (wr_ready !== exp_wr_ready)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=wr_ready got=%0h exp=%0h | rst_n=%0b wr_valid=%0h wr_data=%0h rd_ready=%0h", cyc, cur_seq, i, wr_ready, exp_wr_ready, rst_n, wr_valid, wr_data, rd_ready);
        end
        if (chk_rd_valid && (rd_valid !== exp_rd_valid)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=rd_valid got=%0h exp=%0h | rst_n=%0b wr_valid=%0h wr_data=%0h rd_ready=%0h", cyc, cur_seq, i, rd_valid, exp_rd_valid, rst_n, wr_valid, wr_data, rd_ready);
        end
        if (chk_rd_data && (rd_data !== exp_rd_data)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=rd_data got=%0h exp=%0h | rst_n=%0b wr_valid=%0h wr_data=%0h rd_ready=%0h", cyc, cur_seq, i, rd_data, exp_rd_data, rst_n, wr_valid, wr_data, rd_ready);
        end
        if (chk_count && (count !== exp_count)) begin
            errors++;
            if (errors <= 12)
                $display("MISMATCH cycle=%0d seq=%s i=%0d port=count got=%0h exp=%0h | rst_n=%0b wr_valid=%0h wr_data=%0h rd_ready=%0h", cyc, cur_seq, i, count, exp_count, rst_n, wr_valid, wr_data, rd_ready);
        end
        if (count == 0) cov_hits[0]++;
        if (count == 8) cov_hits[1]++;
        if (count == 8 && wr_valid) cov_hits[2]++;
        if (count == 0 && rd_ready) cov_hits[3]++;
        if (count == 1 && wr_valid && rd_ready) cov_hits[4]++;
        if (count == 7 && wr_valid && rd_ready) cov_hits[5]++;
        if (count == 8 && wr_valid && rd_ready) cov_hits[6]++;
    endtask

    task automatic drive_defaults();
        wr_valid = 1'b0;
        wr_data = 8'h00;
        rd_ready = 1'b0;
    endtask

    initial begin
        drive_defaults();
        rst_n = 1'b0;
        m_reset();
        repeat (3) @(negedge clk);
        rst_n = 1'b1;

        // sequence: random_traffic
        cur_seq = "random_traffic";
        for (i = 0; i < 3000; i++) begin
            @(negedge clk);
            cyc++;
            drive_defaults();
            wr_valid = 1'($urandom_range(0, 1));
            wr_data = 8'($urandom);
            rd_ready = 1'($urandom_range(0, 1));
            rst_n = 1'b1;
            #1;
            if (rst_n == 1'b0) m_reset();
            check();
            @(posedge clk);
            if (rst_n != 1'b0) m_step();
        end

        $display("COVER empty %0d", cov_hits[0]);
        $display("COVER full %0d", cov_hits[1]);
        $display("COVER write_when_full %0d", cov_hits[2]);
        $display("COVER read_when_empty %0d", cov_hits[3]);
        $display("COVER simul_rw_at_1 %0d", cov_hits[4]);
        $display("COVER simul_rw_at_7 %0d", cov_hits[5]);
        $display("COVER simul_rw_when_full %0d", cov_hits[6]);
        $display("CHECKS %0d ERRORS %0d", checks, errors);
        if (errors == 0) $display("PASS"); else $display("FAIL");
        $finish;
    end
endmodule
